namespace EdFi.DmsConfigurationService.Backend.DataStoreProvisioning.Packaging;

/// <summary>
/// The single restore artifact extracted into the operation's private directory (D-5). The path is
/// generated by the stager, never taken from a request; the hash is the manifest's <c>artifactSha256</c>,
/// re-verified while extracting. Step 2.3 delivers the stager that produces it.
/// </summary>
/// <param name="FilePath">The absolute path of the extracted artifact inside the operation directory.</param>
/// <param name="Sha256">Lowercase hex SHA-256 of the artifact bytes.</param>
/// <param name="Kind">Which engine the artifact is for.</param>
public sealed record StagedArtifact(string FilePath, string Sha256, DmsArtifactKind Kind);
